import numpy as np
import pandas as pd
import torch

# download from echonext benchmark
train_tabuler_features = np.load('./data/EchoNext_train_tabular_features.npy')
val_tabuler_features = np.load('./data/EchoNext_val_tabular_features.npy')
test_tabuler_features = np.load('./data/EchoNext_test_tabular_features.npy')
ECG_meta = pd.read_csv('./data/echonext_metadata_100k.csv')


# generated by traditional ECG models:
train_data_pred = torch.load('./data/feature_train.pth')
train_data_pred = train_data_pred['y_pred_test']
train_data_pred = train_data_pred.numpy()

val_data_pred = torch.load('./data/feature_val.pth')
val_data_pred = val_data_pred['y_pred_test']
val_data_pred = val_data_pred.numpy()

test_data_pred = torch.load('./data/feature_test.pth')
test_data_pred = test_data_pred['y_pred_test']
test_data_pred = test_data_pred.numpy()

X_train_STMEM_original = torch.load('./data/feature_train_original.pth')
X_train_STMEM_original = X_train_STMEM_original['y_pred_test']
X_train_STMEM_original = X_train_STMEM_original.numpy()

X_val_STMEM_original = torch.load('./data/feature_valid_original.pth')
X_val_STMEM_original = X_val_STMEM_original['y_pred_test']
X_val_STMEM_original = X_val_STMEM_original.numpy()

X_test_STMEM_original = torch.load('./data/feature_test_original.pth')
X_test_STMEM_original = X_test_STMEM_original['y_pred_test']
X_test_STMEM_original = X_test_STMEM_original.numpy()





label_names = ['lvef_lte_45_flag',
               'lvwt_gte_13_flag',
               'aortic_stenosis_moderate_or_greater_flag',
               'aortic_regurgitation_moderate_or_greater_flag',
               'mitral_regurgitation_moderate_or_greater_flag',
               'tricuspid_regurgitation_moderate_or_greater_flag',
               'pulmonary_regurgitation_moderate_or_greater_flag',
               'rv_systolic_dysfunction_moderate_or_greater_flag',
               'pericardial_effusion_moderate_large_flag',
               'pasp_gte_45_flag',
               'tr_max_gte_32_flag',
               'shd_moderate_or_greater_flag',
               'lvef_value']

ECG_meta_train = ECG_meta[ECG_meta['split'] == 'train']
ECG_meta_val = ECG_meta[ECG_meta['split'] == 'val']
ECG_meta_test = ECG_meta[ECG_meta['split'] == 'test']


def sex_match_engine(list1, list2):
    list3 = [1.0 if i == 'male' else 0.0 for i in list1]
    for j in range(len(list3)):
        if list3[j] != list2[j]:
            print("no match")
            return None
    print('match')
    return 1

def sex_match_check(ECG_meta_pd, tabuler_features_np):
    sex_list = list(ECG_meta_pd['sex'])
    return sex_match_engine(sex_list, tabuler_features_np[:,0])


# check the data
if sex_match_check(ECG_meta_train, train_tabuler_features)==1:
    ECG_meta_train_diag = ECG_meta_train[label_names]
    train_table_final = np.concatenate((train_tabuler_features, train_data_pred), axis=1)

    ECG_meta_train_diag = ECG_meta_train_diag.to_numpy()

if sex_match_check(ECG_meta_val, val_tabuler_features)==1:
    ECG_meta_val_diag = ECG_meta_val[label_names]
    val_table_final = np.concatenate((val_tabuler_features, val_data_pred), axis=1)

    ECG_meta_val_diag = ECG_meta_val_diag.to_numpy()


if sex_match_check(ECG_meta_test, test_tabuler_features)==1:
    ECG_meta_test_diag = ECG_meta_test[label_names]
    test_table_final = np.concatenate((test_tabuler_features, test_data_pred), axis=1)

    ECG_meta_test_diag = ECG_meta_test_diag.to_numpy()



X_train = train_table_final
y_train = ECG_meta_train_diag

X_val = val_table_final
y_val = ECG_meta_val_diag

X_test = test_table_final
y_test = ECG_meta_test_diag










